  // plan page (plan.html); distances, notes and routes come from the place texts and routes.js
  'plan.doctitle': 'Plan your visit · Sanski Most',
  'plan.meta': 'Distances, practical notes and suggested routes for Sanski Most and its surroundings.',
  'plan.eyebrow': 'Visit',
  'plan.title': 'Plan your visit',
  'plan.lead': 'Distances, practical notes and suggested routes for Sanski Most and its surroundings.',
  'plan.dist.title': 'How far from town',
  'plan.dist.note': "Distances are approximate. The 17 km to the Grmeč forest is measured in a straight line from the town centre.",
  'plan.before.title': 'Before you go',
  'plan.when.title': 'When',
  'plan.routes.title': 'Suggested routes',
  'plan.dist.eyebrow': 'Distances',
  'plan.before.eyebrow': 'Practical',
  'plan.when.eyebrow': 'Timing',
  'plan.y.spring.when': 'Spring',
  'plan.y.spring': 'After the snow melts or after heavy rain, Bobijaško oko is at its best.',
  'plan.y.summer.when': 'Summer',
  'plan.y.summer': 'Inside Dabar cave it is about ten degrees cooler than outside, even in summer.',
  'plan.y.musalla.when': 'First Friday in July',
  'plan.y.musalla': 'The Musalla gathering, with the Friday prayer in the open.',
  'plan.y.oct.when': '10 October',
  'plan.y.oct': 'Liberation Day and Municipality Day of Sanski Most.',
  'plan.get.eyebrow': 'Getting here',
  'plan.get.title': 'How to get here',
  'plan.get.bihac': 'about 85 km',
  'plan.get.zagreb': 'by car',
  'plan.get.sarajevo': 'about 220 km',
  'plan.get.air.k': 'Airports',
  'plan.get.air': 'Banja Luka and Zagreb are the nearest; Sarajevo is further.',
  'plan.get.bus.k': 'Bus',
  'plan.get.bus': 'The bus station is on Bulevar VII korpusa. Timetables change, so check them with the operators.',
  'plan.get.town.k': 'In town',
  'plan.get.town': 'Park in the centre and walk along the Sana: the sights in town are within walking distance.',
  'plan.get.note': 'Driving times are approximate and depend on the road and the border.',
  'plan.sum.eyebrow': 'Summer',
  'plan.sum.title': 'Summer on the Sana',
  'plan.sum.lead': 'In summer the town grows several times over: people from Sanski Most who live abroad come home, and visitors with them. In the evening the promenade on Prijedorska street is full.',
  'plan.sum.fest.t': 'The “Ljeto na Sani” festival',
  'plan.sum.fest': 'Held since 1997. It opens in July with the Sladoledijada, an ice-cream party for children in the Mali park on the Zdena, and ends in late July or early August with the traditional jumps from the Town Bridge. In between: concerts, exhibitions and sport. It is organised by RTV “Sana”.',
  'plan.sum.swim.t': 'Swimming',
  'plan.sum.swim': 'In summer people swim in the Sana, on beaches in and around town. In 2026 residents voted for the Gerzovo and Radinovac beaches to be fitted out.',
  'plan.sum.fish.t': 'Fishing',
  'plan.sum.fish': 'The waters of the Sana and its tributaries are managed by the “Sana” sport fishing society, founded in 1950. Ask the society for a permit and the rules.',
  'plan.sum.kayak.t': 'Kayaking',
  'plan.sum.kayak': 'The Sana is calmer than the Una, so kayaking down it suits beginners too.',
  'plan.stay.eyebrow': 'Where to stay',
  'plan.stay.title': 'Where to stay',
  'plan.stay.beds': 'registered beds',
  'plan.stay.hotels': 'hotels and motels',
  'plan.stay.private': 'apartments, rooms and holiday houses',
  'plan.stay.lead': 'The Cat Deluxe and Centar hotels are in the centre. The rest are apartments, rooms and holiday houses in private homes, in town and along the Sana.',
  'plan.stay.tip': 'For July and August, book early: that is when the town is fullest.',
  'plan.stay.spa.k': 'Spa',
  'plan.stay.spa.t': 'Sanska Ilidža',
  'plan.stay.spa': 'About 13 km upstream, at the foot of Mulež: thermal pools, healing mud and rooms. Check the opening hours before you go.',
  'plan.stay.list': 'Official list of accommodation',
  'plan.stay.tz': 'Sanski Most Tourist Board',
  'plan.y.sana.when': '20 July',
  'plan.y.sana': 'Sana River Day; the “Ljeto na Sani” festival is also in July.',
